uot;:[0,697],&quot;slug&quot;:[0,&quot;return-of-the-mount-hua-sect-76&quot;],&quot;postTitle&quot;:[0,&quot;Return of the Mount Hua Sect&quot;],&quot;alternativeTitles&quot;:[0,&quot;화산귀환[독점]   Volcano Return   Return of the Blossoming Blade&quot;],&quot;seriesColor&quot;:[0,&quot;&quot;],&quot;featuredImage&quot;:[0,&quot;https://storage.azoramoon.com/public/upload/series/featured/cmjkgwd7t0000ld63nf9eiyz6/193c3fab-2b1d-454d-8d31-233a6a8ec275.png&quot;],&quot;featuredImageCL&quot;:[0,&quot;&quot;],&quot;featuredLogo&quot;:[0,&quot;&quot;],&quot;hot&quot;:[0,true],&quot;isNew&quot;:[0,false],&quot;seriesStatus&quot;:[0,&quot;ONGOING&quot;],&quot;seriesType&quot;:[0,&quot;MANHWA&quot;],&quot;bannerenabled&quot;:[0,true],&quot;banner&quot;:[0,&quot;&quot;],&quot;bannerHero&quot;:[0,&quot;&quot;],&quot;releaseDate&quot;:[0,&quot;&quot;],&quot;lastChapterAddedAt&quot;:[0,&quot;2026-05-12T20:36:53.957Z&quot;],&quot;postStatus&quot;:[0,&quot;PUBLIC&quot;],&quot;createdAt&quot;:[0,&quot;2021-03-24T14:23:08.000Z&quot;],&quot;updatedAt&quot;:[0,&quot;2026-05-07T20:42:02.943Z&quot;],&quot;isNovel&quot;:[0,false],&quot;isPinned&quot;:[0,true],&quot;chaptersOnSale&quot;:[0,false],&quot;saleActive&quot;:[0,false],&quot;salePercentage&quot;:[0,0],&quot;saleEndDate&quot;:[0,null],&quot;postContent&quot;:[0,&quot;تشينغ مينغ، التلميذ الثالث عشر لطائفة هوسان، أحد السيافين العظماء الثلاثة، تم هزيمة تشيونما، الذي جلب الدمار والفوضى إلى العالم. بعد المعركة، تشينغ مينغ يتنفس أنفاسه الأخيرة على قمة الجبل الرئيسي، ثم يولد من جديد بعد 100 عام في جسد طفل. ……كيف؟ سقطت طائفة هوسان؟ ما نوع الهراء هذا!؟&quot;],&quot;createdby&quot;:[0,null],&quot;genres&quot;:[1,[[0,{&quot;id&quot;:[0,9],&quot;name&quot;:[0,&quot;كوميدي&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,10],&quot;name&quot;:[0,&quot;مانهوا&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,11],&quot;name&quot;:[0,&quot;إثارة&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,15],&quot;name&quot;:[0,&quot;سينين&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,23],&quot;name&quot;:[0,&quot;قوة خارقة&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,32],&quot;name&quot;:[0,&quot;اسبوعي&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,43],&quot;name&quot;:[0,&quot;دموي&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,45],&quot;name&quot;:[0,&quot;مميز&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,1],&quot;name&quot;:[0,&quot;أكشن&quot;],&quot;color&quot;:[0,&quot;&quot;]}]]],&quot;_count&quot;:[0,{&quot;chapters&quot;:[0,168]}],&quot;averageRating&quot;:[0,9.77],&quot;chapters&quot;:[1,[]]}],[0,{&quot;id&quot;:[0,2306],&quot;slug&quot;:[0,&quot;i-only-need-the-duke's-child1&quot;],&quot;postTitle&quot;:[0,&quot;I Only Need the Duke's Child&quot;],&quot;alternativeTitles&quot;:[0,&quot;&quot;],&quot;seriesColor&quot;:[0,&quot;&quot;],&quot;featuredImage&quot;:[0,&quot;https://storage.azoramoon.com/public/upload/series/featured/a5vVlSc5huft2AzUyK1VxgKh1ckCWLbZ/73f74805-6825-4bdf-9b58-de756a705173.png&quot;],&quot;featuredImageCL&quot;:[0,&quot;&quot;],&quot;featuredLogo&quot;:[0,&quot;&quot;],&quot;hot&quot;:[0,false],&quot;isNew&quot;:[0,false],&quot;seriesStatus&quot;:[0,&quot;ONGOING&quot;],&quot;seriesType&quot;:[0,&quot;MANHWA&quot;],&quot;bannerenabled&quot;:[0,true],&quot;banner&quot;:[0,&quot;&quot;],&quot;bannerHero&quot;:[0,&quot;&quot;],&quot;releaseDate&quot;:[0,&quot;&quot;],&quot;lastChapterAddedAt&quot;:[0,&quot;2026-05-12T16:00:39.963Z&quot;],&quot;postStatus&quot;:[0,&quot;PUBLIC&quot;],&quot;createdAt&quot;:[0,&quot;2026-04-07T15:53:08.636Z&quot;],&quot;updatedAt&quot;:[0,&quot;2026-05-13T00:27:07.582Z&quot;],&quot;isNovel&quot;:[0,false],&quot;isPinned&quot;:[0,true],&quot;chaptersOnSale&quot;:[0,false],&quot;saleActive&quot;:[0,false],&quot;salePercentage&quot;:[0,0],&quot;saleEndDate&quot;:[0,null],&quot;postContent&quot;:[0,&quot;&lt;p&gt;بَعد الارتدادِ عبرَ الزَّمن، لم يكن اقتراني بزوجي السابقِ للمرةِ الثانية إلا سَبيلَ الوحيدَ لغايةٍ وحيدة: استعادةُ طفلي. ​لقد كانت حياتي الأولى مفعمةً بالشقاء، مع زوجٍ قاسي القلبِ غليظِ الوجدان، ولم يكن لي فيها من مَلاذٍ سوى طفلي الذي وهبني الأمل.. غير أن تلك الحياة قد وُئِدَت بغتةً على يدِ مجهولٍ غادر. ​«لو قُدّر لي العودةُ إلى الماضي، لن أمنحهُ ذرةً من حُبّي.» ​وهكذا، بِيَقينٍ صلبٍ لا يتزعزع، اخترتُ الزواجَ منه ثانيةً في هذه الحياة التي وُهِبتُها كالمعجزة؛ لا رغبةً في وداده، بل مدفوعةً برغبةٍ جامحةٍ في لقاء طفلي من جديد. ​«فلنُبقِ على هذا الزواجِ لعامٍ واحدٍ فقط.» ​كان الثمنُ هو مساعدته في فكّ طلاسمِ قضيةٍ غامضةٍ تعودُ لعشرِ سنواتٍ خلت. ظننتُ حينها أننا لسنا سوى زوجينِ على ورق، تجمعهما مصلحةٌ ويفرّقهما عقد.. لكنَّ الواقعَ كان مغايرًا تمامًا. ​«ليس بالضرورةِ أن نمضي ليلتنا الأولى كـ...» قاطعني قائلًا بصوتٍ حازم: «لكنني أريدُ ذلك.» ​لقد غدا رجلًا آخرًا، لا يشبهُ ذاك الذي عرفتُه في حياتي الغابرة. ​كانت خطتي تقتضي الرحيلَ في صمتٍ بمجرد أن أحملَ بطفلي.. لكنني حين أبصرتُ المرأةَ التي كانت عشيقتَه في الماضي، لم أستطع كبحَ لسانِي: «تلك المرأة.. هي من سيقعُ في حُبّها فؤادُك.» ​نطقتُ بها لأتجنبَ تكرارَ مأساةِ قدري السابق، غير أن ردَّه جاء مُزلزلًا، لم أتوقعه: «أنتِ زوجتي حتى ينقضي هذا العقد.» ثم أردف بنبرةٍ تملؤها الحِدّة: «وهذه الأفعال، وما هو أعظمُ منها، لن تكونَ إلا معكِ وحدكِ.» ​ارتعدت فرائصي من تملّكه المخيف، وحاولتُ جاهدةً لملمةَ شتاتِ قلبي.. لا تنسي يا \&quot;بلير\&quot;.. هو لا يحبكِ. ​لذا، سأكون أنا في هذه الحياة.. مَن يخطو خطوةَ الفراقِ أولًا.&lt;/p&gt;&quot;],&quot;createdby&quot;:[0,{&quot;name&quot;:[0,&quot;Tiger&quot;]}],&quot;genres&quot;:[1,[[0,{&quot;id&quot;:[0,640],&quot;name&quot;:[0,&quot;رومانسي &quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,59],&quot;name&quot;:[0,&quot;فانتازيا&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,12],&quot;name&quot;:[0,&quot;دراما&quot;],&quot;color&quot;:[0,&quot;&quot;]}]]],&quot;_count&quot;:[0,{&quot;chapters&quot;:[0,11]}],&quot;averageRating&quot;:[0,9],&quot;chapters&quot;:[1,[]]}],[0,{&quot;id&quot;:[0,2463],&quot;slug&quot;:[0,&quot;the-forgotten-field&quot;],&quot;postTitle&quot;:[0,&quot;The Forgotten Field&quot;],&quot;alternativeTitles&quot;:[0,&quot;&quot;],&quot;seriesColor&quot;:[0,&quot;&quot;],&quot;featuredImage&quot;:[0,&quot;https://storage.azoramoon.com/upload/series/featured/oGmL0DQZ16QInTPaeDKwFEK9ryegoy88/c146147d-bc65-428b-ac40-89596d8fd49c.jpg&quot;],&quot;featuredImageCL&quot;:[0,&quot;&quot;],&quot;featuredLogo&quot;:[0,&quot;&quot;],&quot;hot&quot;:[0,false],&quot;isNew&quot;:[0,true],&quot;seriesStatus&quot;:[0,&quot;ONGOING&quot;],&quot;seriesType&quot;:[0,&quot;MANHWA&quot;],&quot;bannerenabled&quot;:[0,true],&quot;banner&quot;:[0,&quot;&quot;],&quot;bannerHero&quot;:[0,&quot;&quot;],&quot;releaseDate&quot;:[0,&quot;&quot;],&quot;lastChapterAddedAt&quot;:[0,&quot;2026-05-12T15:56:08.931Z&quot;],&quot;postStatus&quot;:[0,&quot;PUBLIC&quot;],&quot;createdAt&quot;:[0,&quot;2026-05-04T18:02:31.652Z&quot;],&quot;updatedAt&quot;:[0,&quot;2026-05-07T20:42:05.660Z&quot;],&quot;isNovel&quot;:[0,false],&quot;isPinned&quot;:[0,true],&quot;chaptersOnSale&quot;:[0,false],&quot;saleActive&quot;:[0,false],&quot;salePercentage&quot;:[0,0],&quot;saleEndDate&quot;:[0,null],&quot;postContent&quot;:[0,&quot;&lt;p&gt;كل يوم، أدعو.&lt;/p&gt;&lt;p&gt;أن يموت هذا الحب.&lt;/p&gt;&lt;p&gt;وأن أحبك فقط حتى اليوم،&lt;/p&gt;&lt;p&gt;وغداً، لن يكون لهذا الحب وجود.&lt;/p&gt;&lt;p&gt;الأميرة الإمبراطورية التعيسة تاليا روم غويرتا، المولودة من علاقة غير شرعية، تكبر مشوهة في عالم يرفضها.&lt;/p&gt;&lt;p&gt;مع أبوين غير مبالين، واخوة غير أشقاء معادين، وخدم يعاملونها بازدراء، تنجو من خلال إظهار أشواكها لكل من يجرؤ على الاقتراب.&lt;/p&gt;&lt;p&gt;ومع ذلك، أمام رجل واحد، حتى دفاعات تاليا تنهار.&lt;/p&gt;&lt;p&gt;ذلك الرجل هو باركاس لايدغو سيركان، الوريث النبيل للشرق.&lt;/p&gt;&lt;p&gt;بصفته تابعاً للعائلة الإمبراطورية وخليفة لسلالة دوقية كبرى، فقد أُجبر على الكمال منذ ولادته.&lt;/p&gt;&lt;p&gt;نشأ تحت تدريب كان على وشك الإساءة، مما جعل عواطفه باهتة، تاركاً إياه رجلاً يوجد فقط من أجل شرف العائلة والواجب.&lt;/p&gt;&lt;p&gt;لوفاء بوعد قطعه للإمبراطورة الراحلة، يصبح مخطوباً لأخت تاليا غير الشقيقة الكبرى، آيلا.&lt;/p&gt;&lt;p&gt;محطمة باليأس، تتداعى تاليا ببطء.&lt;/p&gt;&lt;p&gt;ولكن بعد ذلك،&lt;/p&gt;&lt;p&gt;يبدأ حبها، الذي قُدّر له الموت فقط، في مواجهة نقطة تحول غير متوقعة…&lt;/p&gt;&quot;],&quot;createdby&quot;:[0,{&quot;name&quot;:[0,&quot;Rana&quot;]}],&quot;genres&quot;:[1,[[0,{&quot;id&quot;:[0,59],&quot;name&quot;:[0,&quot;فانتازيا&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,640],&quot;name&quot;:[0,&quot;رومانسي &quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,12],&quot;name&quot;:[0,&quot;دراما&quot;],&quot;color&quot;:[0,&quot;&quot;]}]]],&quot;_count&quot;:[0,{&quot;chapters&quot;:[0,21]}],&quot;averageRating&quot;:[0,6.8],&quot;chapters&quot;:[1,[]]}],[0,{&quot;id&quot;:[0,2404],&quot;slug&quot;:[0,&quot;the-tyrant-brother-is-a-bonus&quot;],&quot;postTitle&quot;:[0,&quot;The Tyrant Brother is A Bonus&quot;],&quot;alternativeTitles&quot;:[0,&quot;&quot;],&quot;seriesColor&quot;:[0,&quot;&quot;],&quot;featuredImage&quot;:[0,&quot;https://storage.azoramoon.com/upload/series/featured/02408b52-85d5-445d-9e5c-f7dbcd583bf8/83a1b090-c3a1-458b-bc75-327d1d03aa15.jpg&quot;],&quot;featuredImageCL&quot;:[0,&quot;&quot;],&quot;featuredLogo&quot;:[0,&quot;&quot;],&quot;hot&quot;:[0,false],&quot;isNew&quot;:[0,false],&quot;seriesStatus&quot;:[0,&quot;ONGOING&quot;],&quot;seriesType&quot;:[0,&quot;MANHWA&quot;],&quot;bannerenabled&quot;:[0,true],&quot;banner&quot;:[0,&quot;&quot;],&quot;bannerHero&quot;:[0,&quot;&quot;],&quot;releaseDate&quot;:[0,&quot;&quot;],&quot;lastChapterAddedAt&quot;:[0,&quot;2026-05-12T08:54:59.045Z&quot;],&quot;postStatus&quot;:[0,&quot;PUBLIC&quot;],&quot;createdAt&quot;:[0,&quot;2026-04-26T14:01:03.353Z&quot;],&quot;updatedAt&quot;:[0,&quot;2026-05-12T20:31:20.980Z&quot;],&quot;isNovel&quot;:[0,false],&quot;isPinned&quot;:[0,true],&quot;chaptersOnSale&quot;:[0,false],&quot;saleActive&quot;:[0,false],&quot;salePercentage&quot;:[0,0],&quot;saleEndDate&quot;:[0,null],&quot;postContent&quot;:[0,&quot;&lt;p&gt;حصدتُ من طفرة العملات الرقمية ثروةً تُناطح السحاب، وفي لمحةِ بصر، هوت بي الطائرة صريعةً.. فتبدد كل شيء! ​«سحقًا لهذا الحظ!» ​حين استرددتُ وعيي، وجدتني قد بُعثتُ في جوف رواية، ولم أكن سوى \&quot;الأميرة الشريرة\&quot; في قصةٍ مأساويةٍ صاخبة. ​أهذا حلم؟ ​قيل لي: إن حافظتِ على رابط الخُطوبَة لعامٍ واحد، نردّكِ إلى عالمكِ.. إلى ذلك اليوم المجيد الذي جنيتِ فيه ثمار المليارات! ​يا إلهي، لك الحمد! ظننتُ العقبة هينةً، حتى صدمني الواقع بمُرّه: ​«مجرد قُربكِ مني يبعث في نفسي القرف؛ لذا.. سأفسخ هذا القِران!» ​خطيبي لا يمقتني فحسب، بل ضرب حول قلبه حصنًا منيعًا لا يُخترق! ​آه، لا.. ليس الآن! تمسكتُ به قائلة: \&quot;أرجوك، تريّث معي قليلًا!\&quot; ​«اصطبر عليّ ثلاثة أشهرٍ فحسب.. ماذا لو توليتُ أنا سداد ديونك؟» ​عزمتُ على ادِّعاءَ مساعدته لأشتري الوقت وأصمد عامي المنشود، لكن المصائب لا تأتي فُـرادى، فالعقبة لم تكن في الخطيب وحده! ​«هيه، أنتِ! قُلت تعالي إليّ.. ألم تسمعي؟» ​«أطفئي الانوار.» ​هذا الذي يزعم أنه شقيقي، لا ينفكّ يترصد لي ويختلق المشاكل، والمصيبة الكبرى أنه بطل الرواية الطاغية! ​«ألم آمركِ بالابتعاد عن ذاك الرجل؟ افسخي هذه الخُطبة فورًا!» ​إنه يفسد عليّ خطتي للنجاة! تُرى، هل سأتمكن من العودة بسلام لأعانق ثروتي المفقودة؟&lt;/p&gt;&quot;],&quot;createdby&quot;:[0,{&quot;name&quot;:[0,&quot;Tiger&quot;]}],&quot;genres&quot;:[1,[[0,{&quot;id&quot;:[0,59],&quot;name&quot;:[0,&quot;فانتازيا&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,640],&quot;name&quot;:[0,&quot;رومانسي &quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,12],&quot;name&quot;:[0,&quot;دراما&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,642],&quot;name&quot;:[0,&quot;كوميدي &quot;],&quot;color&quot;:[0,&quot;&quot;]}]]],&quot;_count&quot;:[0,{&quot;chapters&quot;:[0,21]}],&quot;averageRating&quot;:[0,10],&quot;chapters&quot;:[1,[]]}],[0,{&quot;id&quot;:[0,2386],&quot;slug&quot;:[0,&quot;the-youngest-filming-a-childcare-reality-show-is-adorable&quot;],&quot;postTitle&quot;:[0,&quot;The Youngest Filming A Childcare Reality Show Is Adorable &quot;],&quot;alternativeTitles&quot;:[0,&quot;&quot;],&quot;seriesColor&quot;:[0,&quot;&quot;],&quot;featuredImage&quot;:[0,&quot;https://storage.azoramoon.com/public/upload/series/featured/oGmL0DQZ16QInTPaeDKwFEK9ryegoy88/b4c73a33-6bee-421c-b36a-35d96436052f.jpg&quot;],&quot;featuredImageCL&quot;:[0,&quot;&quot;],&quot;featuredLogo&quot;:[0,&quot;&quot;],&quot;hot&quot;:[0,true],&quot;isNew&quot;:[0,true],&quot;seriesStatus&quot;:[0,&quot;ONGOING&quot;],&quot;seriesType&quot;:[0,&quot;MANHWA&quot;],&quot;bannerenabled&quot;:[0,true],&quot;banner&quot;:[0,&quot;&quot;],&quot;bannerHero&quot;:[0,&quot;&quot;],&quot;releaseDate&quot;:[0,&quot;&quot;],&quot;lastChapterAddedAt&quot;:[0,&quot;2026-05-12T08:42:52.774Z&quot;],&quot;postStatus&quot;:[0,&quot;PUBLIC&quot;],&quot;createdAt&quot;:[0,&quot;2026-04-19T18:55:17.773Z&quot;],&quot;updatedAt&quot;:[0,&quot;2026-05-07T20:41:52.653Z&quot;],&quot;isNovel&quot;:[0,false],&quot;isPinned&quot;:[0,true],&quot;chaptersOnSale&quot;:[0,false],&quot;saleActive&quot;:[0,false],&quot;salePercentage&quot;:[0,0],&quot;saleEndDate&quot;:[0,null],&quot;postContent&quot;:[0,&quot;&lt;p&gt;تشو، التي عُثر عليها وحيدةً في الشارع خلال شتاء بارد، كانت تعيش في مركز رعاية نهارية عام.&lt;/p&gt;&lt;p&gt;أذكى من صديقاتها، وشهيةٌ نهمة، تحلم تشو بأن تصبح صاحبة متجر كعك رائع!&lt;/p&gt;&lt;p&gt;لكن...&lt;/p&gt;&lt;p&gt;\&quot;لن أكون ابنة الأميرال! سأخبز الكعك!\&quot;&lt;/p&gt;&lt;p&gt;في أحد الأيام، أصبحت فجأةً مرشحةً للانضمام إلى المستيقظين، وتبنتها عائلة فاساين باسم سوبرتي باساين.&lt;/p&gt;&lt;p&gt;قبلت التبني بعد أن وُعدت بالسماح لها بخبز الكعك حتى في باساين، لكن&lt;/p&gt;&lt;p&gt;[عرض ظهور في برنامج الواقع الخاص بالأبوة والأمومة &amp;lt;طفلي الحبيب&amp;gt;!]&lt;/p&gt;&lt;p&gt;[يقترح عليك ملك الماء، ■■■■، حركة لطيفة بوخز خدك.]&lt;/p&gt;&lt;p&gt;في ظل نظام عروض غريب، حيث يُقال إن جاذبيتك باللطافة تجعلك أقوى (؟)،&lt;/p&gt;&lt;p&gt;تُكمل سوبرتي مهامًا تُلبّي رغبات ملوك الأرواح.&lt;/p&gt;&lt;p&gt;أفراد العائلة سعداء بتلقّي بركات الأرواح...&lt;/p&gt;&lt;p&gt;لكن لماذا ملوك الأرواح صادقون إلى هذا الحد، ولماذا تزداد المهام غرابةً؟!&lt;/p&gt;&lt;p&gt;إنقاذ العالم (؟) باللطافة&lt;/p&gt;&lt;p&gt;قصة نجاة سوبرتي من برنامج منوعات ضخم!&lt;/p&gt;&lt;p&gt;&lt;/p&gt;&quot;],&quot;createdby&quot;:[0,{&quot;name&quot;:[0,&quot;Rana&quot;]}],&quot;genres&quot;:[1,[[0,{&quot;id&quot;:[0,8],&quot;name&quot;:[0,&quot;رومانسي&quot;],&quot;color&quot;:[0,&quot;&quot;]}]]],&quot;_count&quot;:[0,{&quot;chapters&quot;:[0,24]}],&quot;averageRating&quot;:[0,10],&quot;chapters&quot;:[1,[]]}],[0,{&quot;id&quot;:[0,2330],&quot;slug&quot;:[0,&quot;i-am-the-5-year-old-spy-who-kidnapped-the-villain&quot;],&quot;postTitle&quot;:[0,&quot;I Am the 5-Year-Old Spy Who Kidnapped the Villain&quot;],&quot;alternativeTitles&quot;:[0,&quot;&quot;],&quot;seriesColor&quot;:[0,&quot;&quot;],&quot;featuredImage&quot;:[0,&quot;https://storage.azoramoon.com/public/upload/series/featured/02408b52-85d5-445d-9e5c-f7dbcd583bf8/1329119b-bed9-4428-a26e-7b26fcc7eb77.jpg&quot;],&quot;featuredImageCL&quot;:[0,&quot;&quot;],&quot;featuredLogo&quot;:[0,&quot;&quot;],&quot;hot&quot;:[0,false],&quot;isNew&quot;:[0,true],&quot;seriesStatus&quot;:[0,&quot;ONGOING&quot;],&quot;seriesType&quot;:[0,&quot;MANHWA&quot;],&quot;bannerenabled&quot;:[0,true],&quot;banner&quot;:[0,&quot;&quot;],&quot;bannerHero&quot;:[0,&quot;&quot;],&quot;releaseDate&quot;:[0,&quot;&quot;],&quot;lastChapterAddedAt&quot;:[0,&quot;2026-05-12T07:14:12.475Z&quot;],&quot;postStatus&quot;:[0,&quot;PUBLIC&quot;],&quot;createdAt&quot;:[0,&quot;2026-04-12T06:54:14.630Z&quot;],&quot;updatedAt&quot;:[0,&quot;2026-05-07T20:41:53.985Z&quot;],&quot;isNovel&quot;:[0,false],&quot;isPinned&quot;:[0,true],&quot;chaptersOnSale&quot;:[0,false],&quot;saleActive&quot;:[0,false],&quot;salePercentage&quot;:[0,0],&quot;saleEndDate&quot;:[0,null],&quot;postContent&quot;:[0,&quot;&lt;p&gt;تعرّفوا على آيشا،، الجاسوسة ذات الخمس سنوات التي ربّتها عائلة بوز. \&quot;مهمتكِ الأولى: أن تصبحي الابنة المفقودة للدوق كاليبس كروست.\&quot; داخل جسدها، أُرسلتُ للإطاحة بالدوق كاليبس كروست... أنا، التي مُتُّ من الإرهاق، دخلتُ. لا يمكنني أن أموت كما في القصة الأصلية، متظاهرةً بأنني ابنة مزيفة! يومًا بعد يوم، أسعى جاهدةً للتحرر من حياة الجاسوسة، كاشفةً مكان الابنة الحقيقية، ومعترفًا بي كحليفة بطرقٍ شتى. حتى أنني اخترتُ أبًا بالتبني لأتجنب العودة إلى عائلة بوز. \&quot;بقدراتي، يُمكنني أن أصبح مرتزقةً من الفئة S. ماذا لو حاولتم رعاية هذه البذرة الذهبية التي أُطلقت عليّ؟\&quot; وأخيرًا، اليوم الذي تُثمر فيه الجهود ويُستلم طلب التبني. \&quot;حان الآن وقت التعارف الرسمي.\&quot; لماذا يبدو الرجل العجوز، الذي خلع رداءه المعتاد، وسيماً للغاية؟ لماذا غرفته فخمةٌ كغرف النبلاء، ولماذا يجثو الناس عند دخولهم؟ \&quot;...سيدي، من أنت؟\&quot;&lt;/p&gt;&quot;],&quot;createdby&quot;:[0,{&quot;name&quot;:[0,&quot;Tiger&quot;]}],&quot;genres&quot;:[1,[[0,{&quot;id&quot;:[0,640],&quot;name&quot;:[0,&quot;رومانسي &quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,60],&quot;name&quot;:[0,&quot;عائلي&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,7],&quot;name&quot;:[0,&quot;خيال&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,943],&quot;name&quot;:[0,&quot;اطفال&quot;],&quot;color&quot;:[0,&quot;&quot;]}]]],&quot;_count&quot;:[0,{&quot;chapters&quot;:[0,24]}],&quot;averageRating&quot;:[0,9.8],&quot;chapters&quot;:[1,[]]}],[0,{&quot;id&quot;:[0,1508],&quot;slug&quot;:[0,&quot;the-counts-secret-maid&quot;],&quot;postTitle&quot;:[0,&quot;The Count's Secret Maid&quot;],&quot;alternativeTitles&quot;:[0,&quot;&quot;],&quot;seriesColor&quot;:[0,&quot;&quot;],&quot;featuredImage&quot;:[0,&quot;https://storage.azoramoon.com/2024/11/IMG_20250218_022548_148-scaled.jpg&quot;],&quot;featuredImageCL&quot;:[0,&quot;&quot;],&quot;featuredLogo&quot;:[0,&quot;&quot;],&quot;hot&quot;:[0,false],&quot;isNew&quot;:[0,false],&quot;seriesStatus&quot;:[0,&quot;ONGOING&quot;],&quot;seriesType&quot;:[0,&quot;MANHWA&quot;],&quot;bannerenabled&quot;:[0,true],&quot;banner&quot;:[0,&quot;&quot;],&quot;bannerHero&quot;:[0,&quot;&quot;],&quot;releaseDate&quot;:[0,&quot;&quot;],&quot;lastChapterAddedAt&quot;:[0,&quot;2026-05-11T22:14:22.343Z&quot;],&quot;postStatus&quot;:[0,&quot;PUBLIC&quot;],&quot;createdAt&quot;:[0,&quot;2024-11-05T12:50:02.000Z&quot;],&quot;updatedAt&quot;:[0,&quot;2026-05-11T22:45:06.774Z&quot;],&quot;isNovel&quot;:[0,false],&quot;isPinned&quot;:[0,true],&quot;chaptersOnSale&quot;:[0,false],&quot;saleActive&quot;:[0,false],&quot;salePercentage&quot;:[0,0],&quot;saleEndDate&quot;:[0,null],&quot;postContent&quot;:[0,&quot;كانت \&quot;باولا\&quot; فتاة قبيحة للغاية ولدت في أسرة فقيرة. وبمحض الصدفة، تم توظيفها كخادمة في قصر الكونت بيلونيتا الشهير. ولكن، كان سيدها \&quot;فينسنت بيلونيتا\&quot;، الذي فقد بصره، يعيش في خوف شديد مختبئًا بين جدران غرفته... وكان على باولا أن تعتني به وحدها في سرية تامة حتى يستطيع الخروج إلى العالم مرة أخرى.&quot;],&quot;createdby&quot;:[0,null],&quot;genres&quot;:[1,[[0,{&quot;id&quot;:[0,7],&quot;name&quot;:[0,&quot;خيال&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,8],&quot;name&quot;:[0,&quot;رومانسي&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,12],&quot;name&quot;:[0,&quot;دراما&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,25],&quot;name&quot;:[0,&quot;غموض&quot;],&quot;color&quot;:[0,&quot;&quot;]}]]],&quot;_count&quot;:[0,{&quot;chapters&quot;:[0,89]}],&quot;averageRating&quot;:[0,9.7],&quot;chapters&quot;:[1,[]]}],[0,{&quot;id&quot;:[0,2329],&quot;slug&quot;:[0,&quot;marriage-defense-scandal&quot;],&quot;postTitle&quot;:[0,&quot;Marriage defense scandal&quot;],&quot;alternativeTitles&quot;:[0,&quot;&quot;],&quot;seriesColor&quot;:[0,&quot;&quot;],&quot;featuredImage&quot;:[0,&quot;https://storage.azoramoon.com/public/upload/series/featured/6cac1de1-87ae-4a81-9cd1-2abe99fd84d7/7b5b9ddd-b977-4efa-a89c-5941fe817708.png&quot;],&quot;featuredImageCL&quot;:[0,&quot;&quot;],&quot;featuredLogo&quot;:[0,&quot;&quot;],&quot;hot&quot;:[0,false],&quot;isNew&quot;:[0,false],&quot;seriesStatus&quot;:[0,&quot;ONGOING&quot;],&quot;seriesType&quot;:[0,&quot;MANHWA&quot;],&quot;bannerenabled&quot;:[0,true],&quot;banner&quot;:[0,&quot;&quot;],&quot;bannerHero&quot;:[0,&quot;&quot;],&quot;releaseDate&quot;:[0,&quot;&quot;],&quot;lastChapterAddedAt&quot;:[0,&quot;2026-05-11T16:50:08.446Z&quot;],&quot;postStatus&quot;:[0,&quot;PUBLIC&quot;],&quot;createdAt&quot;:[0,&quot;2026-04-11T22:06:25.484Z&quot;],&quot;updatedAt&quot;:[0,&quot;2026-05-07T20:41:28.616Z&quot;],&quot;isNovel&quot;:[0,false],&quot;isPinned&quot;:[0,true],&quot;chaptersOnSale&quot;:[0,false],&quot;saleActive&quot;:[0,false],&quot;salePercentage&quot;:[0,0],&quot;saleEndDate&quot;:[0,null],&quot;postContent&quot;:[0,&quot;&lt;p style=\&quot;text-align: center;\&quot;&gt;تشاي إيون آه تملك كل شيء، الجمال، والمال، والذكاء. بصفتها الحفيدة الصغرى لعائلة ثرية، ظنت أن بلوغها العشرين يعني أن العالم أصبح بين يديها... إلى أن فاجأها جدها بكلمة \&quot;زواج\&quot;. الزواج؟! تُشكّل بطاقاتها الائتمانية المصادرة أزمة، لكن الكارثة الحقيقية هي عريسها، عدوها اللدود وحبيبها السابق! تابعوا حياة إيون آه السرية في الجامعة وهي تُناضل لحماية زواجها، أو بالأحرى، عاداتها الشرائية.&lt;/p&gt;&quot;],&quot;createdby&quot;:[0,{&quot;name&quot;:[0,&quot;V!cTooR&quot;]}],&quot;genres&quot;:[1,[[0,{&quot;id&quot;:[0,29],&quot;name&quot;:[0,&quot;شوجو&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,640],&quot;name&quot;:[0,&quot;رومانسي &quot;],&quot;color&quot;:[0,&quot;&quot;]}]]],&quot;_count&quot;:[0,{&quot;chapters&quot;:[0,11]}],&quot;averageRating&quot;:[0,3.67],&quot;chapters&quot;:[1,[]]}],[0,{&quot;id&quot;:[0,2393],&quot;slug&quot;:[0,&quot;the-scorched-desert's-sand-mage&quot;],&quot;postTitle&quot;:[0,&quot;Sand Mage of the Scorched Desert&quot;],&quot;alternativeTitles&quot;:[0,&quot;&quot;],&quot;seriesColor&quot;:[0,&quot;&quot;],&quot;featuredImage&quot;:[0,&quot;https://storage.azoramoon.com/upload/series/featured/6cac1de1-87ae-4a81-9cd1-2abe99fd84d7/59fb6295-bdbc-42b7-a61c-a9e01e7095ac.jpg&quot;],&quot;featuredImageCL&quot;:[0,&quot;&quot;],&quot;featuredLogo&quot;:[0,&quot;&quot;],&quot;hot&quot;:[0,false],&quot;isNew&quot;:[0,false],&quot;seriesStatus&quot;:[0,&quot;ONGOING&quot;],&quot;seriesType&quot;:[0,&quot;MANHWA&quot;],&quot;bannerenabled&quot;:[0,true],&quot;banner&quot;:[0,&quot;&quot;],&quot;bannerHero&quot;:[0,&quot;&quot;],&quot;releaseDate&quot;:[0,&quot;&quot;],&quot;lastChapterAddedAt&quot;:[0,&quot;2026-05-09T14:42:06.352Z&quot;],&quot;postStatus&quot;:[0,&quot;PUBLIC&quot;],&quot;createdAt&quot;:[0,&quot;2026-04-23T18:41:29.118Z&quot;],&quot;updatedAt&quot;:[0,&quot;2026-05-07T20:41:32.006Z&quot;],&quot;isNovel&quot;:[0,false],&quot;isPinned&quot;:[0,true],&quot;chaptersOnSale&quot;:[0,false],&quot;saleActive&quot;:[0,false],&quot;salePercentage&quot;:[0,0],&quot;saleEndDate&quot;:[0,null],&quot;postContent&quot;:[0,&quot;&lt;p style=\&quot;text-align: center;\&quot;&gt;بعد تحويل الأرض إلى بيئة صالحة للسكن، اختفت البحار وتحول العالم إلى رمال لا نهاية لها. في هذه الأرض المدمرة، يقف زيون كساحر الرمال الوحيد المتبقي. يخشاه الآخرون باسم شبح الرمال، ويستخدم الصحراء بأكملها كسلاح في عالم وحشي شكلته الخراب والبقاء.&lt;/p&gt;&lt;p style=\&quot;text-align: center;\&quot;&gt;&lt;/p&gt;&quot;],&quot;createdby&quot;:[0,{&quot;name&quot;:[0,&quot;V!cTooR&quot;]}],&quot;genres&quot;:[1,[[0,{&quot;id&quot;:[0,10],&quot;name&quot;:[0,&quot;مانهوا&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,414],&quot;name&quot;:[0,&quot;اكشن&quot;],&quot;color&quot;:[0,&quot;&quot;]}]]],&quot;_count&quot;:[0,{&quot;chapters&quot;:[0,21]}],&quot;averageRating&quot;:[0,5],&quot;chapters&quot;:[1,[]]}],[0,{&quot;id&quot;:[0,2324],&quot;slug&quot;:[0,&quot;the-grand-duke-has-awakened-in-a-strange-place&quot;],&quot;postTitle&quot;:[0,&quot;The Grand Duke Has Awakened in a Strange Place&quot;],&quot;alternativeTitles&quot;:[0,&quot;&quot;],&quot;seriesColor&quot;:[0,&quot;&quot;],&quot;featuredImage&quot;:[0,&quot;https://storage.azoramoon.com/public/upload/series/featured/02408b52-85d5-445d-9e5c-f7dbcd583bf8/99741558-746d-48df-b171-3e9b501d3887.png&quot;],&quot;featuredImageCL&quot;:[0,&quot;&quot;],&quot;featuredLogo&quot;:[0,&quot;&quot;],&quot;hot&quot;:[0,false],&quot;isNew&quot;:[0,true],&quot;seriesStatus&quot;:[0,&quot;ONGOING&quot;],&quot;seriesType&quot;:[0,&quot;MANHWA&quot;],&quot;bannerenabled&quot;:[0,true],&quot;banner&quot;:[0,&quot;&quot;],&quot;bannerHero&quot;:[0,&quot;&quot;],&quot;releaseDate&quot;:[0,&quot;&quot;],&quot;lastChapterAddedAt&quot;:[0,&quot;2026-05-09T08:25:33.516Z&quot;],&quot;postStatus&quot;:[0,&quot;PUBLIC&quot;],&quot;createdAt&quot;:[0,&quot;2026-04-10T11:49:34.958Z&quot;],&quot;updatedAt&quot;:[0,&quot;2026-05-07T20:41:27.220Z&quot;],&quot;isNovel&quot;:[0,false],&quot;isPinned&quot;:[0,true],&quot;chaptersOnSale&quot;:[0,false],&quot;saleActive&quot;:[0,false],&quot;salePercentage&quot;:[0,0],&quot;saleEndDate&quot;:[0,null],&quot;postContent&quot;:[0,&quot;&lt;p&gt;\&quot;ألن تخبريني اليوم أنني جميل؟\&quot; كيف تحوّل من رجل بريء وخجول إلى رجل مغوٍ مندفع وصريح؟ === \&quot;تظاهري بأنكِ الآنسة، وحافظي على خطبة العائلة.\&quot; تجسدتُ داخل رواية حريم عكسي للبالغين… والأسوأ أنني مجرد شخصية إضافية مثقلة بالديون، لم يُذكر اسمها حتى في سطر واحد من الرواية…! وبينما كنت أعيش أسدد ديوني، إذا بالبطلة—أملي الوحيد—تموت أمام عيني؟ وفي خضم ذلك، تطلب عائلة البطلة مني، أنا العامية، أن أحل محلها كنبيلة. كنت على وشك الرفض والمغادرة دون تردد، لكن— \&quot;خمسة ملايين مينت.\&quot; مبلغ يكفي لسداد ديوني وزيادة… فاستجاب جسد العامية الفقيرة قبل عقلي. لم تكن سوى نزوة صغيرة… أن أفتح عينيّ خطيبي المسكين قبل أن أرحل. لكن، ما الذي حدث بحق— \&quot;ألن تخبريني اليوم أنني جميل؟\&quot; كيف تحوّل من رجل ساذج ومهذب إلى رجل مغوٍ مباشر هكذا؟! أنت لم تكن بهذا النوع من الشخصيات في الأصل! \&quot;سأجعلكِ تقعِين في حبي، سينثيا.\&quot; تألقت عيناه البنفسجيتان، اللتان كانتا دائمًا مخفيتين تحت جفنيه، بظلمة عميقة. \&quot;لذا، أحبّيني بأسرع ما يمكن، سينثيا.\&quot;&lt;/p&gt;&quot;],&quot;createdby&quot;:[0,{&quot;name&quot;:[0,&quot;Tiger&quot;]}],&quot;genres&quot;:[1,[[0,{&quot;id&quot;:[0,65],&quot;name&quot;:[0,&quot;خيالي&quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,640],&quot;name&quot;:[0,&quot;رومانسي &quot;],&quot;color&quot;:[0,&quot;&quot;]}],[0,{&quot;id&quot;:[0,9],&quot;name&quot;:[0,&quot;كوميدي&quot;],&quot;color&quot;:[0,&quot;&quot;]}]]],&quot;_count&quot;:[0,{&quot;chapters&quot;:[0,25]}],&quot;averageRating&quot;:[0,9],&quot;chapters&quot;:[1,[]]}]]],&quot;cdnOptions&quot;:[0,{&quot;photonEnabled&quot;:[0,true],&quot;coverPhoton&quot;:[0,true]}],&quot;styleNumber&quot;:[0,1]}" client="visible" opts="{&quot;name&quot;:&quot;HomepageMainSliderIsland&quot;,&quot;value&quot;:{&quot;rootMargin&quot;:&quot;80px&quot;}}" await-children=""><section class="h-[430px] mainSlider"><style>
